// Validate, normalise and classify an inbound lead.
// Throws -> the Error Workflow (WF-D) fires. Never silently drops a lead.
const cfg = $env ?? {};
const raw = $input.first().json;
const body = (raw.body && typeof raw.body === 'object') ? raw.body : raw;

// 1. Honeypot. A bot filling the hidden field looks exactly like a real post.
if (body._gotcha) { return [{ json: { reject: true, code: 400, reason: 'honeypot' } }]; }

// 2. Required fields. `name` is compulsory on the site form too (name, email,
//    services, timeline and budget are its five required fields), so an absent
//    one is a malformed post rather than a legitimate anonymous enquiry.
const name = String(body.name ?? body.client_name ?? '').trim();
if (!name) { return [{ json: { reject: true, code: 400, reason: 'missing name' } }]; }

// ponytail: REJECTING an implausible name -- not sanitising it -- is what makes
// leads.name trustworthy on the round trip. WF-B reads this column straight back
// out and renders it into a DMARC-aligned mail, so escaping at that one sink
// would still leave the database holding attacker-authored copy for every other
// consumer (operator inbox, CRM export, any future template). Allow-list only:
// letters, combining marks, space, both apostrophe forms, dot, hyphen; 60 max.
if (!/^[\p{L}\p{M}][\p{L}\p{M} '’.-]{0,59}$/u.test(name)) {
  return [{ json: { reject: true, code: 400, reason: 'invalid name' } }];
}

// 3. Normalise. email_norm / phone_norm are the partial-unique-index keys, so
//    normalisation IS the dedupe rule -- keep it boring and deterministic.
const emailRaw = String(body.email ?? '').trim().toLowerCase();
const email = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(emailRaw) ? emailRaw : null;

let phone = String(body.phone ?? '').replace(/[^\d+]/g, '');
if (phone.startsWith('0'))       phone = '+27' + phone.slice(1);   // ZA local -> E.164
else if (phone.startsWith('27')) phone = '+' + phone;
if (phone && !/^\+\d{8,15}$/.test(phone)) phone = null;
if (!phone) phone = null;

// ponytail: email is now the only automated channel, so a lead without a valid
// one is unreachable and there is nothing to queue. The site form already makes
// email required; phone stays optional and is only there for a human callback.
if (!email) {
  return [{ json: { reject: true, code: 400, reason: 'missing or invalid email' } }];
}

// 4. Classify. Rules come from config, not hardcoded, so a new vertical is a
//    config edit rather than a workflow edit.
const timeline = String(body.timeline ?? '').toLowerCase();
const budget   = String(body.budget   ?? '').toLowerCase();
const topic    = String(body.topic    ?? '').toLowerCase();
// ponytail: these fallbacks are the ONLY urgency rule whenever these env vars are
// unset, and both previous values were stale -- `lt-1-month` and `100k-150k`
// exist in neither of the site's enums (timelines: asap|1-3m|3-6m|exploring,
// budgets: lt-25k|25-75k|75-150k|150k-plus, contact-submit.js:45-53), so they
// could never match and the urgent branch fired on roughly half its intended
// triggers. With SMS gone the ntfy push is the only urgent-alert channel, so a
// missed trigger is now a silently dropped SLA. Values mirror the defaults in
// config.example.json.
//
// Env vars are flat strings, but config.example.json expresses these two as JSON
// arrays (the followup_days convention). A bare .split(',') on `["asap"]` yields
// one junk element and matches nothing, so accept array, JSON-array-string and
// comma-separated string alike -- otherwise 'in sync with the config' holds only
// while these env vars are unset, which is exactly the case nobody tests.
const enumList = (v, fallback) => {
  const s = String(v ?? fallback).trim();
  let out = null;
  if (s.startsWith('[')) { try { out = JSON.parse(s); } catch (e) { out = null; } }
  if (!Array.isArray(out)) out = s.split(',');
  return out.map(x => String(x).trim().toLowerCase()).filter(Boolean);
};
const urgentTimelines = enumList(cfg.urgent_timelines, 'asap');
const urgentBudgets   = enumList(cfg.urgent_budgets, '75-150k,150k-plus');
const urgent = urgentTimelines.includes(timeline) || urgentBudgets.includes(budget);

// ponytail: service_type is pushed to a world-readable ntfy topic (the topic
// name itself now lives only in Vault -- see vault/secrets.md -- not in git),
// and it sits OUTSIDE the HMAC base, so it must be a value we chose rather
// than text the visitor typed -- otherwise
// `service="Jane Doe jane@acme.co.za +2782..."` is published publicly, and ntfy
// autolinks bare URLs, making the owner's own push a phishing surface.
// Unmatched -> null, NOT a rejection: an unrecognised service is unclassifiable,
// not an attack, and the lead is still worth having.
// Mirrors ALLOWED_SERVICES in the site's functions/contact-submit.js -- the four
// current pillars plus three pre-repositioning transitional aliases
// (software-dev, cloud-devops, ai-engineering) kept so a visitor holding a cached
// copy of the old page is not silently misclassified. Drop the aliases when the
// site drops them; they were scheduled for removal after 2026-09-01 (ADR-015).
const SERVICES = new Set(['automation','seo','digital-marketing','advisory',
                          'software-dev','cloud-devops','ai-engineering']);
const serviceIn = String(body.service ?? body.topic ?? '').trim().toLowerCase();
const service = SERVICES.has(serviceIn) ? serviceIn : null;

// 5. Signature base. Signing a fixed string beats signing the raw body: no JSON
//    canonicalisation mismatch between Cloudflare Workers and n8n.
const ref  = String(body.submissionId ?? body.ref ?? '').trim();
const ts   = String(body.submittedAt ?? '').trim();
const skew = ts ? Math.abs(Date.now() - Date.parse(ts)) / 1000 : Infinity;
if (!ref || !ts)      return [{ json: { reject: true, code: 400, reason: 'missing ref/timestamp' } }];
if (!(skew < 300))    return [{ json: { reject: true, code: 401, reason: 'stale or unparseable timestamp' } }];

return [{ json: {
  reject: false,
  sigBase: `${ref}.${ts}.${email ?? phone}`,
  providedSig: String(body.signature ?? ''),
  lead: {
    email_norm: email, phone_norm: phone, name,
    service_type: service,
    urgency: urgent ? 'urgent' : 'normal',
    consent_source: 'website_form',
  },
  submission: {
    ref, source: String(body.source ?? 'website'),
    utm_source: body.utm_source ?? null, utm_medium: body.utm_medium ?? null,
    utm_campaign: body.utm_campaign ?? null,
    entry_point: body.entryPoint ?? body.entry_point ?? null, topic: topic || null,
    // Full body verbatim, including the pre-enum `service` string: constraining
    // service_type above narrows what we PUBLISH, never what we KEEP.
    raw: JSON.stringify(body),
  },
} }];
